import 'package:flex_color_scheme/flex_color_scheme.dart';
import 'package:flutter/material.dart';

/// Builds the app theme for [brightness].
///
/// The theme is generated by flex_color_scheme from [FlexScheme.tealM3] with
/// low surface levels (scaffold uses `surface`). This reproduces the app's
/// existing color set (previously captured from `FlexColorScheme.toScheme`
/// with the same configuration) while flex applies a consistent sub-theme
/// style to every Material component.
ThemeData buildAppTheme(Brightness brightness) {
  return brightness == Brightness.dark
      ? FlexThemeData.dark(
          scheme: FlexScheme.tealM3,
          surfaceMode: FlexSurfaceMode.levelSurfacesLowScaffold,
          blendLevel: 2,
          fontFamily: 'Inter',
          subThemesData: _subThemesData,
        )
      : FlexThemeData.light(
          scheme: FlexScheme.tealM3,
          surfaceMode: FlexSurfaceMode.levelSurfacesLowScaffold,
          blendLevel: 1,
          fontFamily: 'Inter',
          subThemesData: _subThemesData,
        );
}

const FlexSubThemesData _subThemesData = FlexSubThemesData(
  inputDecoratorBorderType: FlexInputBorderType.outline,
  inputDecoratorRadius: 16.0,
  cardRadius: 16.0,
  cardElevation: 0,
  dialogRadius: 20.0,
  dialogElevation: 0,
  bottomSheetElevation: 0,
  navigationBarElevation: 0,
  navigationRailElevation: 0,
  navigationRailUseIndicator: true,
  appBarScrolledUnderElevation: 0,
  elevatedButtonElevation: 0,
  popupMenuElevation: 2,
);
